parts.text:
[
  {
    "statement": "There are no studies that have evaluated the effects of releasing captive-bred bats on bat populations.",
    "citations": [
      "2039"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects of breeding bats in captivity specifically to supplement wild populations affected by white-nose syndrome.",
    "citations": [
      "2009"
    ]
  },
  {
    "statement": "Studies have documented the successful captive breeding of bats.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "In captivity, 6-100% of female bats have successfully conceived, given birth, and reared young.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "In captive settings, 20-100% of bat pups have survived from 10 days to adulthood.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "There is no evidence available regarding the success rates of reintroducing captive-bred bats into wild populations, particularly in areas affected by white-nose syndrome.",
    "citations": []
  },
  {
    "statement": "The only related evidence on bat reintroduction comes from rehabilitation studies.",
    "citations": [
      "2054"
    ]
  },
  {
    "statement": "In rehabilitation studies, 70-90% of hand-reared pipistrelle bats survived for at least 4-14 days after release into the wild.",
    "citations": [
      "2054"
    ]
  },
  {
    "statement": "In one study, six of 21 hand-reared bats joined wild bat colonies after release.",
    "citations": [
      "2054"
    ]
  },
  {
    "statement": "In another study, 13% of ringed hand-reared bats were found alive 38 days to almost four years after release.",
    "citations": [
      "2054"
    ]
  }
]

[
  {
    "statement": "No studies have been found that evaluated the effects on bat populations of training arborists and forestry operatives to identify potential bat roosts.",
    "citations": [
      "1981"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects on bat populations of protecting roost trees during forest operations.",
    "citations": [
      "1982"
    ]
  },
  {
    "statement": "There is currently no evidence available to assess whether training arborists and forestry operatives to identify potential bat roosts is effective or has any harmful impacts.",
    "citations": [
      "1981"
    ]
  },
  {
    "statement": "There is currently no evidence available to assess whether protecting roost trees during forest operations is effective or has any harmful impacts.",
    "citations": [
      "1982"
    ]
  },
  {
    "statement": "No comparison of effectiveness between training arborists to identify potential bat roosts and protecting roost trees during forest operations can be made based on the available evidence.",
    "citations": [
      "1981",
      "1982"
    ]
  }
]
